    const args = [resolve(root, 'scripts/evaluate-narrative-reader-local-codex.mjs'), '--inputs', resolve(temporary, 'inputs.json'),
      '--protocol', resolve(temporary, 'protocol.json'), '--output', output, '--dry-run']
